import{_ as a,o as e,c as o,a5 as r}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"状态机","description":"状态机简介 状态机（State Machine）是一个模型，它由一些称作“状态”的东西组成。这个模型可以在不同的状态之间进行切换，就像一个机器人或者游戏中的角色，它根据当前的情况来决定下一步做什么。 状态机的组成 状态机主要由以下几个部分组成： 状态（States） ：这些是系统。","frontmatter":{"title":"状态机","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"状态机简介 状态机（State Machine）是一个模型，它由一些称作“状态”的东西组成。这个模型可以在不同的状态之间进行切换，就像一个机器人或者游戏中的角色，它根据当前的情况来决定下一步做什么。 状态机的组成 状态机主要由以下几个部分组成： 状态（States） ：这些是系统。","sidebarWeight":9,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/HJ74 参数解析/状态机.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/HJ74 参数解析/状态机.md","filePath":"posts/前端面试与实战/03-算法训练/HJ74 参数解析/状态机.md"}'),i={name:"posts/前端面试与实战/03-算法训练/HJ74 参数解析/状态机.md"};function s(n,t,l,d,c,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<div><h1 id="状态机" tabindex="-1">状态机 <a class="header-anchor" href="#状态机" aria-label="Permalink to &quot;状态机&quot;">​</a></h1><blockquote><p>本节目标：理解“状态机”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><h3 id="状态机简介" tabindex="-1">状态机简介 <a class="header-anchor" href="#状态机简介" aria-label="Permalink to &quot;状态机简介&quot;">​</a></h3><p>状态机（State Machine）是一个模型，它由一些称作“状态”的东西组成。这个模型可以在不同的状态之间进行切换，就像一个机器人或者游戏中的角色，它根据当前的情况来决定下一步做什么。</p><h3 id="状态机的组成" tabindex="-1">状态机的组成 <a class="header-anchor" href="#状态机的组成" aria-label="Permalink to &quot;状态机的组成&quot;">​</a></h3><p>状态机主要由以下几个部分组成：</p><ul><li><strong>状态（States）</strong>：这些是系统可能处于的所有不同情况。例如，一个交通信号灯可能有“红灯”、“黄灯”和“绿灯”三种状态。</li><li><strong>事件（Events）</strong>：这些是触发从一个状态过渡到另一个状态的活动或条件。例如，如果我们有一个停表（计时器），“计时结束”可能是一个事件，它会从“正在计时”状态切换到“停止”状态。</li><li><strong>转换（Transitions）</strong>：这些是在事件发生时状态间的具体切换。例如，停表的“重置按钮被按下”是一个转换，它会将停表从任何状态重置到“初始”状态。</li><li><strong>动作（Actions）</strong>：这些是因响应事件而在状态机内部执行的活动。例如，停表可能会在“计时结束”时响铃。</li></ul><h3 id="状态机的类型" tabindex="-1">状态机的类型 <a class="header-anchor" href="#状态机的类型" aria-label="Permalink to &quot;状态机的类型&quot;">​</a></h3><ul><li><strong>有限状态机（FSM, Finite State Machine）</strong>：在有限状态机中，状态的数量是有限的，且预先定义好的。这是最简单的状态机类型。</li><li><strong>扩展状态机（Extended State Machine）</strong>：除了有限的状态外，扩展状态机还可以有变量和条件，这些变量可以影响转换发生的方式。</li></ul><h3 id="状态机的例子" tabindex="-1">状态机的例子 <a class="header-anchor" href="#状态机的例子" aria-label="Permalink to &quot;状态机的例子&quot;">​</a></h3><p>我们可以用一个简单的例子来说明状态机是如何工作的：考虑一个电梯的运作。</p><ul><li><strong>状态</strong>：&#39;静止在一楼&#39;，&#39;上升&#39;，&#39;静止在二楼&#39;，&#39;下降&#39;。</li><li><strong>事件</strong>：&#39;乘客进入&#39;，&#39;达到楼层&#39;，&#39;乘客离开&#39;。</li><li><strong>转换</strong>：当在一楼且&#39;乘客进入&#39;事件发生时，电梯状态从&#39;静止在一楼&#39;转变为&#39;上升&#39;。</li><li><strong>动作</strong>：在&#39;上升&#39;状态时，电梯内的指示灯可能会点亮。</li></ul><h3 id="使用状态机的优势" tabindex="-1">使用状态机的优势 <a class="header-anchor" href="#使用状态机的优势" aria-label="Permalink to &quot;使用状态机的优势&quot;">​</a></h3><ul><li><strong>明确性</strong>：状态机通过有限的状态和规则，让复杂的逻辑变得清晰易懂。</li><li><strong>预测性</strong>：给定任何状态和事件，你都能准确预知状态机将如何响应。</li><li><strong>可维护性</strong>：状态机使得添加新的状态和转换变得更加容易。</li></ul><h3 id="状态机在编程中的应用" tabindex="-1">状态机在编程中的应用 <a class="header-anchor" href="#状态机在编程中的应用" aria-label="Permalink to &quot;状态机在编程中的应用&quot;">​</a></h3><p>在编程中，状态机经常用来管理复杂的逻辑。例如，你可能会在一个游戏中用状态机来管理角色的行为，或者在一个应用程序中用状态机来管理用户界面（UI）的状态。编程语言和库中有很多方式来实现状态机，例如使用<code>switch</code>/<code>case</code>语句，特殊的状态机库，或者设计模式如状态设计模式（State Design Pattern）。</p><p>希望这个简单的教程能帮助你理解状态机是什么，以及它们是如何工作的！如果你想深入学习或实践状态机，可以尝试用你最喜欢的编程语言来实现一个简单的状态机。</p></div>',1)])])}const p=a(i,[["render",s]]);export{u as __pageData,p as default};
